function burst(x,y,color,n=8){for(let i=0;i<n;i++){let a=Math.random()*TAU,s=25+Math.random()*110;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.45+Math.random()*.55,max:.9,color,size:2+Math.random()*4})}}
function attack(){if(scene!=='play'||attackCooldown>0)return;attackCooldown=.48;const cx=player.x+player.faceX*35,cy=player.y+player.faceY*35;burst(cx,cy,'#e7d995',12);for(const e of enemies){if(!e.alive)continue;let dx=e.x-player.x,dy=e.y-player.y,d=Math.hypot(dx,dy),dot=(dx*player.faceX+dy*player.faceY)/(d||1);if(d<82&&(dot>.12||d<44)){e.hp--;e.hit=.25;e.x+=player.faceX*21;e.y+=player.faceY*21;burst(e.x,e.y,'#b4e6a3',7);if(e.hp<=0){e.alive=false;player.kills++;player.xp++;burst(e.x,e.y,'#d7f0a8',17);showToast('Sprite freed!  +1 starlight');if(player.xp%3===0){player.level++;player.maxHp=Math.min(6,player.maxHp+1);player.hp=player.maxHp;showToast('Level up!  A little stronger ✦')}checkQuest()}}}updateUI()}
function dash(){if(scene!=='play'||dashCooldown>0)return;dashCooldown=1.35;player.inv=.42;let dx=stick.x,dy=stick.y;if(Math.hypot(dx,dy)<.15){dx=player.faceX;dy=player.faceY}let l=Math.hypot(dx,dy)||1;player.x=clamp(player.x+dx/l*105,20,W-20);player.y=clamp(player.y+dy/l*105,20,H-20);burst(player.x,player.y,'#c7e1a3',10)}
function talk(){if(scene!=='play')return;let d=Math.hypot(player.x-900,player.y-625);if(d>110){showToast('The lantern is a little farther north ✧');return}if(questStep===0){questStep=1;dialogue('Mira','Oh! A traveler between worlds. I’m Mira, keeper of this grove. Three moon petals and three shy sprites—would you help me light the lantern?');showToast('Quest started · Petals & sprites');updateUI()}else if(questStep===1){if(player.shards>=3&&player.kills>=3){questStep=2;dialogue('Mira','You did it! The lantern remembers every little kindness. I think the grove has chosen you, Aria.');updateUI();setTimeout(()=>{if(scene==='play'&&questStep===2){scene='end';ui.end.classList.remove('hidden')}},3400)}else dialogue('Mira',`The lantern still needs a little starlight. You have ${player.shards}/3 petals and have freed ${player.kills}/3 sprites. Take your time, traveler.`)}else if(questStep===2){dialogue('Mira','The path between worlds is never truly closed. Wherever you go, you can carry a little magic with you.');scene='end';ui.end.classList.remove('hidden')}}
function dialogue(name,text){document.getElementById('speaker').textContent=name;document.getElementById('dialogueText').textContent=text;ui.dialogue.style.display='block';setTimeout(()=>{if(questStep===1&&player.shards>=3&&player.kills>=3)checkQuest()},20)}
function checkQuest(){if(questStep===1&&player.shards>=3&&player.kills>=3){questStep=2;updateUI();showToast('The lantern is ready. Find Mira! ✦')}}
function update(dt){tick+=dt;if(scene!=='play')return;attackCooldown=Math.max(0,attackCooldown-dt);dashCooldown=Math.max(0,dashCooldown-dt);player.inv=Math.max(0,player.inv-dt);let mx=stick.x,my=stick.y;if(keys.a||keys.arrowleft)mx-=1;if(keys.d||keys.arrowright)mx+=1;if(keys.w||keys.arrowup)my-=1;if(keys.s||keys.arrowdown)my+=1;let mag=Math.hypot(mx,my);if(mag>1){mx/=mag;my/=mag}if(mag>.05){player.faceX=mx;player.faceY=my;player.walk+=dt*10;player.x=clamp(player.x+mx*190*dt,22,W-22);player.y=clamp(player.y+my*190*dt,22,H-22)}
for(const p of petals){if(!p.taken&&Math.hypot(p.x-player.x,p.y-player.y)<27){p.taken=true;player.shards++;burst(p.x,p.y,'#f4db88',13);showToast('Moon petal gathered ✦');updateUI();checkQuest()}}
for(const e of enemies){if(!e.alive)continue;e.phase+=dt*2.2;e.hit=Math.max(0,e.hit-dt);let dx=player.x-e.x,dy=player.y-e.y,d=Math.hypot(dx,dy);if(d<220){e.x+=dx/(d||1)*40*dt;e.y+=dy/(d||1)*40*dt}else{e.x=e.homeX+Math.sin(e.phase)*20;e.y=e.homeY+Math.cos(e.phase*.8)*17}if(d<29&&player.inv<=0){player.hp--;player.inv=.9;burst(player.x,player.y,'#ff9681',9);updateUI();showToast('A sprite booped you!');if(player.hp<=0){player.hp=3;player.x=900;player.y=730;updateUI();showToast('A warm lantern glow restores you ✧')}}}
for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.08,dt);p.vy*=Math.pow(.08,dt);p.life-=dt}particles=particles.filter(p=>p.life>0);camera.x+=(player.x-camera.x)*Math.min(1,dt*5);camera.y+=(player.y-camera.y)*Math.min(1,dt*5);if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show')}
let near=Math.hypot(player.x-900,player.y-625)<112;if(near){setHint('TAP TALK  ·  E to speak');hintTimer=0}else if(hintTimer<2){setHint('Move · Explore · Cast');hintTimer+=dt}else setHint('');
if(keys.e){keys.e=false;talk()}if(keys.shift){keys.shift=false;dash()}}

