function drawSlime(e){let bob=Math.sin(tick*4+e.phase)*3,scale=e.hit>0?1.12:1;ctx.save();ctx.translate(e.x,e.y+bob);ctx.scale(scale,1);ctx.fillStyle='rgba(20,37,29,.28)';ctx.beginPath();ctx.ellipse(0,12,20,7,0,0,TAU);ctx.fill();let gr=ctx.createLinearGradient(-15,-18,15,12);gr.addColorStop(0,e.hit?'#e7ffd0':'#b9dc91');gr.addColorStop(1,e.hit?'#8fbd76':'#74a96d');ctx.fillStyle=gr;ctx.beginPath();ctx.moveTo(-17,5);ctx.quadraticCurveTo(-22,-7,-13,-18);ctx.quadraticCurveTo(0,-29,13,-18);ctx.quadraticCurveTo(22,-7,17,5);ctx.quadraticCurveTo(0,15,-17,5);ctx.fill();ctx.fillStyle='#32463a';ctx.beginPath();ctx.arc(-6,-8,2,0,TAU);ctx.arc(6,-8,2,0,TAU);ctx.fill();ctx.fillStyle='#fff5d6';ctx.fillRect(-6,-10,1,1);ctx.fillRect(6,-10,1,1);ctx.strokeStyle='#596f4e';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(0,-3,3,.2,Math.PI-.2);ctx.stroke();if(e.hp<e.maxHp){ctx.fillStyle='#263a30';ctx.fillRect(-13,-34,26,3);ctx.fillStyle='#e99c78';ctx.fillRect(-13,-34,26*(e.hp/e.maxHp),3)}ctx.restore()}
function drawPetal(p){let pulse=.6+.4*Math.sin(tick*3+p.phase);ctx.save();ctx.translate(p.x,p.y);ctx.fillStyle=`rgba(248,218,132,${.1+.08*pulse})`;ctx.beginPath();ctx.arc(0,0,19+3*pulse,0,TAU);ctx.fill();ctx.rotate(Math.sin(tick+p.phase)*.18);ctx.fillStyle='#f0da98';ctx.beginPath();ctx.ellipse(0,-3,5,10,0,0,TAU);ctx.fill();ctx.fillStyle='#fff0c1';ctx.beginPath();ctx.ellipse(-1,-5,2,5,-.3,0,TAU);ctx.fill();ctx.restore()}
function draw(){ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,vw,vh);let focal=player||{x:900,y:730};let cx=clamp(camera.x,vw/2,W-vw/2),cy=clamp(camera.y,vh/2,H-vh/2);if(vw>W)cx=W/2;if(vh>H)cy=H/2;ctx.save();ctx.translate(vw/2-cx,vh/2-cy);drawGround();
const treesPos=[[90,110,1.3],[230,220,1.05],[1620,140,1.35],[1715,350,1.2],[160,1040,1.4],[350,1150,1.15],[1560,1110,1.25],[1735,930,1.3],[330,370,.8],[1480,520,.9],[240,760,1],[1470,830,1],[650,180,.75],[1180,1060,.85],[1270,160,.8],[560,1050,.9],[1140,360,.65],[440,600,.75],[1330,660,.7]];for(let t of treesPos)drawTree(t[0],t[1],t[2]);drawLantern();
let sprites=[];if(petals)for(let p of petals)if(!p.taken)sprites.push({y:p.y,fn:()=>drawPetal(p)});if(enemies)for(let e of enemies)if(e.alive)sprites.push({y:e.y,fn:()=>drawSlime(e)});sprites.push({y:592,fn:drawMira});if(player)sprites.push({y:player.y,fn:drawPlayer});else sprites.push({y:730,fn:()=>{let p=player;player={x:900,y:730,walk:0,inv:0,faceX:1,faceY:0};drawPlayer();player=p}});sprites.sort((a,b)=>a.y-b.y);for(let s of sprites)s.fn();for(let p of particles){ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,TAU);ctx.fill()}ctx.globalAlpha=1;
// floating wisps
for(let i=0;i<13;i++){let x=160+randSeed(i+500)*1480+Math.sin(tick*.5+i)*19,y=130+randSeed(i+600)*990+Math.cos(tick*.7+i)*16,a=.3+.3*Math.sin(tick*2+i);ctx.fillStyle=`rgba(226,231,165,${a})`;ctx.beginPath();ctx.arc(x,y,1.3+randSeed(i)*1.5,0,TAU);ctx.fill()}ctx.restore();}
function frame(now){let dt=Math.min(.04,(now-last)/1000||0);last=now;update(dt);draw();requestAnimationFrame(frame)}requestAnimationFrame(frame);
</script>
